   "সিঁড়ি: 1NF atomic মান চায় (cell-এ তালিকা নয় — ER পাঠের নিয়ম)। 2NF একটি composite key-র অংশের উপর নির্ভরতা সরায় (একটি (order, product) row-তে customer-এর শহর কোনোটিতেই নির্ভরশীল নয় — তা customer-এর উপর নির্ভরশীল, যার এই table-এ থাকাই উচিত নয়)। 3NF transitive নির্ভরতা সরায় (শহর customer-এর উপর নির্ভরশীল, customer order-এর সঙ্গে চড়ে আসে — customer আলাদা করো)। BCNF শেষ কোণটি শক্ত করে: প্রতিটি determinant-কে candidate key হতে হবে। অপরাধী FD বরাবর ভাগ করো, দরকারে lossless join করে ফিরে পাও — সেই বাক্যটাই পুরো পরীক্ষার বিষয়।"
