   "স্তরের নাম আছে ও গুরুত্বপূর্ণ: unit (একটি function), integration (একসঙ্গে উপাদান — Level 27-এর schema এই level-এর code-এর সঙ্গে মিলিত), system (পুরোটা), acceptance (দুই পাঠ আগের user-এর story, সম্পাদিত)। Suite-এর অর্থনৈতিক বিস্ময় হলো পুনরাবৃত্তি: একবার লেখা হলে একটি test প্রতিটি ভবিষ্যৎ পরিবর্তনের পরে system আবার যাচাই করে — regression-এর একমাত্র জানা প্রতিষেধক।"
