   "k-NN বিপরীত design পছন্দ করে: কোনো মানানো parameterই নয় — তুমি যেসব প্রতিবেশীর মতো তাদের দিয়ে শ্রেণিবিন্যাস করো। দুটোই supervised; দুটোই তাদের মূল্যায়নের মতোই সৎ (পাঠ 6), কারণ training বিন্দু মুখস্থ করা একটি fit (overfitting) অতীত নিখুঁতভাবে ভবিষ্যদ্বাণী করে ও ভবিষ্যৎ খারাপভাবে। Train/test ভাগ ঠিক তা ধরতেই আছে।"
