   "Precision ও recall দুটোই একসঙ্গে সর্বোচ্চ হবে এমনভাবে সর্বোত্তম করা: flag করা সীমা একটিকে অন্যটির বিরুদ্ধে বিনিময় করে; বিনিময় বাছতে হবে, ইচ্ছা করে দূর করা যায় না।",
   "Training data-তে মূল্যায়ন (পাঠ 3-এর পাপ, পরিমাপ আকারে পুনরাবৃত্ত): test পরিমাপ এমন data থেকে আসতে হবে যা model কখনো মানায়নি।"
