  "lab": "Guided lab: পরিষ্কার শুরু থেকে উদাহরণটি (metrics_lab.py) আবার চালাও — চালানোর আগে প্রতিটি ধাপ মুখে বলে; প্রতিটি বর্ণনা why-panel-এর সঙ্গে মেলাও। তারপর Labs অংশে এই level-এর lab খুললে তা সম্পূর্ণ করো।",
