  "summary": "মূল্যায়ন confusion matrix দিয়ে classifier নিরীক্ষণ করে: সার্বিক accuracy, মিথ্যা alarm-এর খরচের জন্য precision, মিসের খরচের জন্য recall — আর শ্রেণি ভারসাম্যহীনতায় precision/recall হলো যেসব সংখ্যা ভদ্রভাবে মিথ্যা বলতে পারে না।",
  "skillGained": "একটি matrix থেকে precision/recall/accuracy হিসাব করা ও পরিস্থিতি খরচ দিয়ে অগ্রাধিকার পরিমাপ বাছাই।",
